INSERT INTO `anuncios` VALUES ('07ca9498-5aab-11f1-a334-5811223fa053','04875bd0-5aab-11f1-a334-5811223fa053','Voluntariado limpieza playas','Este sábado por la mañana organizamos una jornada de limpieza y mantenimiento del parque comunitario. Plantaremos flores nuevas, limpiaremos las zonas de juego, pintaremos los bancos y arreglaremos las instalaciones. Es una actividad ideal para familias con niños, donde enseñamos el valor del cuidado de los espacios comunes. Al finalizar compartiremos un picnic juntos. ¡Hagamos de nuestro parque un lugar aún más bonito!','comunidad',NULL,1,1,'País Vasco','Guipúzcoa',NULL,'compra',1,1,0,1,'approved',NULL,796,'2026-05-23 13:34:20','2026-06-15 20:00:31',NULL,NULL,NULL),('07caac32-5aab-11f1-a334-5811223fa053','0487621d-5aab-11f1-a334-5811223fa053','Busco diseñador/a gráfico freelance','Maestro/a con especialidad en educación primaria busca sustitución o puesto interino. 5 años de experiencia en colegios públicos y concertados. Especializado en metodologías activas y atención a la diversidad. Disponibilidad inmediata y para trabajar en toda la provincia. Busco centro educativo con buen ambiente donde poder aportar mi experiencia. Interesado en proyectos bilingües o innovadores.','empleo',NULL,1,1,'Cantabria','Cantabria',NULL,'compra',1,1,0,1,'approved',NULL,823,'2026-05-13 13:34:20','2026-06-15 20:00:31',NULL,NULL,NULL),('07cab052-5aab-11f1-a334-5811223fa053','0487582f-5aab-11f1-a334-5811223fa053','Busco trabajo en ventas comerciales','Técnico informático con certificaciones Cisco y Microsoft busca puesto de responsable de TI. 8 años de experiencia gestionando infraestructuras de pequeñas y medianas empresas. Dominio de redes, seguridad, virtualización y soporte técnico. Busco empresa donde pueda implementar mejoras y optimizar sistemas. Disponibilidad para guardias y urgencias. Salario esperado: 2400-2800Ôé¼ brutos/mes según responsabilidades.','empleo',NULL,1,1,'Castilla y León','Segovia',NULL,'regalo',1,0,0,1,'pending',NULL,112,'